import React from "react";
import styled from "styled-components";

const TableContainer = styled.div`
  width: 100%;
  background: white;
  padding: 20px;
  border-radius: 8px;
  box-shadow: 0px 4px 6px rgba(0, 0, 0, 0.1);
  margin-top: 30px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow-x: auto; /* Cho phép cuộn ngang nếu bảng quá rộng */
`;

const Title = styled.h3`
  font-size: 40px;
  font-weight: bold;
  margin-bottom: 30px;
  text-align: center;
`;

const TableWrapper = styled.div`
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
`;

const Table = styled.table`
  width: auto; /* Điều chỉnh bảng theo nội dung */
  min-width: 100%;
  border-collapse: collapse;
`;

const Th = styled.th`
  background: #d6d6d6;
  color: black;
  padding: 10px;
  text-align: left;
  white-space: nowrap; /* Giữ nội dung không bị xuống dòng */
`;

const Td = styled.td`
  border: 1px solid #ddd;
  padding: 10px;
  white-space: nowrap;
`;

const AmrTable = ({ data }) => {
    if (!data || data.length === 0) {
      return <p>No data available</p>;
    }
  
    const rows = data.split("\n").map((row) => row.split("\t"));
    if (rows.length === 0 || rows[0].length === 0) {
      return <p>Invalid data format</p>;
    }
  
    let headers = rows[0];
    let body = rows.slice(1);
  
    const excludeColumns = ["Type", "Subtype", "HMM accession", "HMM description", "Protein id"];
    const excludeIndexes = headers
      .map((col, index) => (excludeColumns.includes(col) ? index : -1))
      .filter((index) => index !== -1);
  
    headers = ["STT", ...headers.filter((_, index) => !excludeIndexes.includes(index))];
  
    body = body.map((row, rowIndex) => [
      rowIndex + 1,
      ...row.filter((_, index) => !excludeIndexes.includes(index)),
    ]);
  
    return (
      <TableContainer>
        <Title>AMR Data</Title>
        <TableWrapper>
          <Table>
            <thead>
              <tr>
                {headers.map((header, index) => (
                  <Th key={index}>{header}</Th>
                ))}
              </tr>
            </thead>
            <tbody>
              {body.map((row, rowIndex) => (
                <tr key={rowIndex}>
                  {row.map((cell, cellIndex) => (
                    <Td key={cellIndex}>{cell}</Td>
                  ))}
                </tr>
              ))}
            </tbody>
          </Table>
        </TableWrapper>
      </TableContainer>
    );
  };
  

export default AmrTable;
